        ppAddToCartBtn.style.background = "#0B2545";
        ppAddToCartBtn.style.color = "#FFFFFF";
        ppAddToCartBtn.style.borderColor = "#0B2545";
        ppAddToCartBtn.style.cursor = "not-allowed";
