                ppAddToCartBtn.style.background = "";
                ppAddToCartBtn.style.color = "";
                ppAddToCartBtn.style.borderColor = "";
                ppAddToCartBtn.style.cursor = "pointer";
                const span = ppAddToCartBtn.querySelector("span");
                if (span) {
                  span.textContent = "Add to Cart";
                  span.style.color = "";
                }
